    try:
        from mem0 import MemoryClient  # type: ignore

        return MemoryClient
    except ImportError:
        from mem0ai import MemoryClient  # type: ignore

        return MemoryClient


def _extract_memory_text(result: Dict[str, Any]) -> str:
    for key in ("memory", "text", "memory_text", "content"):
